code_sketch:
struct StoredMessage: Codable, FetchableRecord, PersistableRecord {
    static let databaseTableName = "msg_store"
    var messageId, channel: String
    var recordedAt: Date
    var payload: String                  // already redacted
}
var config = Configuration()
config.journalMode = .wal                // readers do not block the writer
let dbQueue = try DatabaseQueue(path: "audit.sqlite", configuration: config)
let tap = DispatchQueue(label: "message-store")     // single writer, off the flow
func record(_ m: StoredMessage) {
    tap.async { try? dbQueue.write { try m.insert($0) } }   // best effort: count failures
}
